import { html , render , WebComponent , customElement , attr , attrState , state, css, ViewTemplate, ViewContext, asyncAppend, repeat, children } from '@lithium-framework/core';
import '@lithium-framework/router-element';
import 'unofficial-pf-v5-wc';
import 'unofficial-pf-v5-wc-icons';
import '../../components';

@customElement({
  name: 'page-cours',
  template: html`${(cours: Cours) => {
    return html`
      <pf-page masterhead-no-icon masterhead-no-branding drawer-inline drawer-expanded drawer-static drawer-panel-left>
          <div slot = "drawer-panel">
            <navigation-panel></navigation-panel>
          </div>
          <pf-panel header scrollable>
            <h1 slot="header">Informations</h1>
            <div class="table-infos">
              ${asyncAppend(cours.preloadData(), (result) => {
                                    return html`
                                    <div class="raw-infos">
                                        ${
                                            repeat(
                                                result, 
                                                html`${(cour) => {
                                                    return html`
                                                        <div class="row">
                                                            <div class="type-de-cours">${cour.type_cours}</div>
                                                            <div class="date">${cours.formatDateFromISO(cour.date_cours)}</div>
                                                            <div class="heure-debut">${cour.heure_debut}</div>
                                                            <div class="heure-fin">${cour.heure_fin}</div>
                                                        </div>`;
                                                }}`
                                            )
                                        }
                                    </div>
                                    `;
                                })}
            </div>
          </pf-panel>
        <pf-avatar></pf-avatar>
      </pf-page>`;
  }}`,
  styles : [
    css`
      .table-infos {
        color: black;
      }
      .navigation{
        color: black
      }
    `
  ]
})

export class Cours extends WebComponent {
  data: any[] = [];

  register(cour){
    console.log(cour)
  }


  async preloadData(): Promise<any[]> {
    try {

  
      const response = await fetch('http://localhost:3000/cours', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        }
      });
  
      if (!response.ok) {
        throw new Error('Erreur serveur.');
      }
  
      const data = await response.json();
  
      // Enveloppe l'objet dans un tableau
      const dataArray = [data];
  
      console.log('Données récupèrées', dataArray);
  
      return dataArray.length > 0 ? dataArray : []; // Retourne le tableau, ou un tableau vide si aucun élément
    } catch (error) {
      console.error('Erreur lors de la requête fetch:', error);
      return [];
    }
  }

  formatDateFromISO(isoDateString: string): string {
    const date = new Date(isoDateString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  convertToISODate(dateString: string): string {
    const [year, month, day] = dateString.split('-');
    return new Date(`${year}-${month}-${day}T00:00:00Z`).toISOString();
  }
  
}


let template: ViewTemplate<any> = html`${( context:ViewContext )=>{


  return html`<page-cours></page-cours>`;

}}`



render(template);